// Turn raw sheet rows into clean, predictable fields.
// Blank or badly formatted rows are dropped instead of breaking the run.
const out = [];

function num(v, fallback) {
  const n = Number(String(v === undefined || v === null ? '' : v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : fallback;
}

function parseDate(v) {
  if (!v) return null;
  const s = String(v).trim();
  // Accept YYYY-MM-DD, DD/MM/YYYY and DD-MM-YYYY
  let m = s.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})$/);
  if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  m = s.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})$/);
  if (m) return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

for (const item of $input.all()) {
  const r = item.json;
  const id = String(r['Customer ID'] || '').trim();
  const email = String(r['Email'] || '').trim();
  const renewal = parseDate(r['Renewal Date']);

  if (!id || !email.includes('@') || !renewal) continue;

  out.push({
    json: {
      customerId: id,
      customerName: String(r['Customer Name'] || id).trim(),
      email: email,
      plan: String(r['Plan'] || 'Standard').trim(),
      renewalDate: renewal.toISOString().slice(0, 10),
      contractValue: num(r['Contract Value'], 0),
      usageScore: num(r['Usage Score'], 50),
      openTickets: num(r['Open Tickets'], 0),
      lastStageSent: String(r['Last Reminder Stage'] || '').trim(),
      ownerEmail: String(r['Owner Email'] || '').trim(),
    },
  });
}

return out;

// Decide which rung of the reminder ladder each customer is on, and how
// risky that renewal looks. Only one email per rung, ever.
const LADDER = [
  { stage: 'T-30', from: 22, to: 30 },
  { stage: 'T-7',  from: 4,  to: 21 },
  { stage: 'T-1',  from: 0,  to: 3  },
];

const ORDER = { '': 0, 'T-30': 1, 'T-7': 2, 'T-1': 3 };
const today = new Date();
const todayUtc = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  const d = new Date(r.renewalDate + 'T00:00:00Z');
  const daysLeft = Math.round((d.getTime() - todayUtc) / 86400000);

  // Already renewed or long past: nothing to chase here.
  if (daysLeft < 0 || daysLeft > 30) continue;

  const rung = LADDER.find(function (l) { return daysLeft >= l.from && daysLeft <= l.to; });
  if (!rung) continue;

  // Never send the same rung twice, and never go backwards down the ladder.
  if ((ORDER[r.lastStageSent] || 0) >= ORDER[rung.stage]) continue;

  // Risk score: low usage, open tickets and a near date all push it up.
  let risk = 0;
  if (r.usageScore < 25) risk += 45;
  else if (r.usageScore < 50) risk += 25;
  else if (r.usageScore < 70) risk += 10;

  risk += Math.min(30, r.openTickets * 10);

  if (daysLeft <= 3) risk += 20;
  else if (daysLeft <= 7) risk += 10;

  if (r.contractValue >= 5000) risk += 10;

  risk = Math.max(0, Math.min(100, risk));

  let tier = 'Healthy';
  if (risk >= 70) tier = 'High risk';
  else if (risk >= 40) tier = 'Watch';

  let tone = 'friendly and brief';
  if (tier === 'Watch') tone = 'warm, and gently point at the value they already got';
  if (tier === 'High risk') tone = 'helpful and direct, offer a short call to sort things out';

  out.push({
    json: Object.assign({}, r, {
      daysLeft: daysLeft,
      stage: rung.stage,
      riskScore: risk,
      riskTier: tier,
      tone: tone,
      runDate: new Date(todayUtc).toISOString().slice(0, 10),
    }),
  });
}

// Most urgent first, then biggest contracts.
out.sort(function (a, b) {
  return a.json.daysLeft - b.json.daysLeft || b.json.contractValue - a.json.contractValue;
});

return out;

