// One readable summary of the whole run for the account team.
const rows = $('Score Risk and Pick Stage').all().map(function (i) { return i.json; });

const byStage = { 'T-30': 0, 'T-7': 0, 'T-1': 0 };
let value = 0;
const highRisk = [];

for (const r of rows) {
  if (byStage[r.stage] !== undefined) byStage[r.stage] += 1;
  value += r.contractValue;
  if (r.riskTier === 'High risk') highRisk.push(r);
}

const lines = [];
lines.push('*Renewal reminders sent today*');
lines.push('Total reminders: ' + rows.length + '  |  Contract value in play: ' + Math.round(value));
lines.push('30 days out: ' + byStage['T-30'] + '   7 days out: ' + byStage['T-7'] + '   Tomorrow: ' + byStage['T-1']);

if (highRisk.length) {
  lines.push('');
  lines.push('*Needs a human this week*');
  for (const r of highRisk.slice(0, 10)) {
    lines.push('- ' + r.customerName + ' (' + r.plan + ', renews ' + r.renewalDate +
      ', risk ' + r.riskScore + ', usage ' + r.usageScore + ', open tickets ' + r.openTickets + ')');
  }
  if (highRisk.length > 10) lines.push('- and ' + (highRisk.length - 10) + ' more');
} else {
  lines.push('');
  lines.push('No high risk renewals in this batch.');
}

return [{ json: { summary: lines.join('\n'), total: rows.length, highRisk: highRisk.length } }];
